test('6956：双 context sessionStorage 隔离 + 我的页登录名不同', async () => {
  const base = process.env.E2E_BASE_URL || 'http://127.0.0.1:8162'
  const ts = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 15)
  const browser = await chromium.launch()
  const c1 = await browser.newContext()
  const c2 = await browser.newContext()
  const p1 = await c1.newPage()
  const p2 = await c2.newPage()

  async function wireGetInfo(page: typeof p1, userName: string, nickName: string) {
    await page.route('**/v2.0/system/user/getInfo**', async (route) => {
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          code: 200,
          user: { userName, nickName, userId: userName },
        }),
      })
    })
    await page.route('**/v2.0/**', async (route) => {
      const url = route.request().url()
      if (url.includes('/system/user/getInfo')) return
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ code: 200, data: {}, rows: [], total: 0 }),
      })
    })
  }

  async function seed(page: typeof p1, userName: string, nickName: string) {
    await wireGetInfo(page, userName, nickName)
    await page.goto(base, { waitUntil: 'domcontentloaded' })
